from t1 import t
# ---------------- W1: MCP surface ----------------
t(id="MC-1", slug="unknown-paper-id-raises", title="Raise an error for an unknown paper_id filter instead of returning empty",
  s=["S-08"], wave=1, area=["mcp"], tier="Sonnet", size="S",
  why="`filters.paper_id` with an unknown or wrongly formed id returns an empty result with no error, while `get_paper` raises for the same id. In the standards usage log one call with an `arxiv:`-prefixed id (row 327) returned empty and the next with the bare stored id (row 337) succeeded (RV-4 F-4.2, confirmed by the review). An agent reads the empty result as 'this standard does not discuss X'.",
  in_=["In `McpServer.semantic_search` and `search_papers`: when `filters.paper_id` is set, resolve it against the document store; on a miss raise `ContractError` with the same wording style as `get_paper` plus a hint when the id starts with `arxiv:` (the stored form has no prefix).","Reuse the existing `get_paper` resolution and error construction; no new lookup path."],
  out=["Dropping the absolute database path from error text and other error rewording (RV-4 F-4.9, not carried by the review). Fuzzy nearest-id suggestions. Any contract change."],
  owns=["rag/mcp_server.py","rag/test_mcp_server.py"],
  commits=["stub: docstring lines stating the new precondition and error","failing tests: unknown id raises; `arxiv:`-prefixed id raises with the stripped hint; known id still returns results","implementation to green","docstring updated"],
  verify=["`conda run -n agent-rag-research python -m pytest -q rag/test_mcp_server.py -o addopts=\"--disable-socket\"`"],
  accept="Unit tests: an unknown id raises `ContractError`; the `arxiv:`-prefixed form produces the hint; a valid id is unchanged. Mutation proof: remove the resolve call and the unknown-id test fails. Falsified if the unknown-id test passes with the resolve call removed.",
  deps=[], gates=["MC-2"],
  risk="A valid-but-unindexed paper id now errors where it used to return empty. That is intended; it is also the same behaviour `get_paper` already has. Rollback: revert.",
  docs="PROJECT-STATUS ledger via EP-3."),

t(id="MC-2", slug="self-describing-mcp-server", title="Make the MCP server describe its corpus, filters and limits",
  s=["S-10"], wave=1, area=["mcp"], tier="Sonnet", size="M",
  why="A cold agent sees no server instructions, zero field descriptions in the `SearchFilters` schema, and docstring guidance that FastMCP never exposes; `doc_type` was used 0 times in 1,198 logged calls, and wrong-corpus queries appear in the main log (ids 8, 21-24) (RV-4 F-4.3, F-4.4; review S-10). Hard-coded counts and a stale 32-ceiling paragraph in docstrings can disagree with the corpus.",
  in_=["Pass `instructions=` to `FastMCP`, generated at startup from `corpus_stats()` (what the corpus is, counts, date range, document kinds, which filters are meaningful, a five-line tool map), under 250 tokens.","A compact filter legend in the `semantic_search` tool docstring (the field schema is protected). Delete hard-coded counts and the 32-ceiling paragraph.","`corpus_stats` gains a compact `documents` list (id, title, kind, year, status) when the corpus has 500 documents or fewer; kind and status are read from the standards metadata tags if present (CQ-5), omitted otherwise (no hard dependency)."],
  out=["Field descriptions on `SearchFilters` (contracts edit, RIDER-1 territory). A per-corpus card file or Config key. Federation across corpora. Response slimming (MC-4)."],
  owns=["app/serve.py","app/test_serve.py","rag/mcp_server.py","rag/test_mcp_server.py"],
  commits=["stub: docstring stating the instructions contract (generated, under 250 tokens, no literal counts)","failing tests: `instructions` present and under budget; every filter named in the legend; no number in any description absent from `corpus_stats`; `documents` present only at 500 documents or fewer","implementation to green","docstring cleanup commit"],
  verify=["`list_tools` and `initialize().instructions` dump built on fakes (no GPU, no store); output quoted in the PR","`conda run -n agent-rag-research python -m pytest -q app/test_serve.py rag/test_mcp_server.py -o addopts=\"--disable-socket\"`"],
  accept="Instructions exist and stay under 250 tokens on a standards-sized and a main-sized fake; every filter appears in the legend; no description contains a literal count that disagrees with `corpus_stats`. Falsified if a description number is not derived from `corpus_stats`.",
  deps=["MC-1"], gates=["MC-3"],
  risk="Generated text that is wrong for a corpus misleads every cold session. Mitigation: the text is derived from `corpus_stats` only; a test pins that. Rollback: revert.",
  docs="PROJECT-STATUS section 2 (what the server advertises) via EP-3."),

t(id="MC-3", slug="scan-tool-telemetry", title="Record arguments and errors for scan and get tools in the usage log",
  s=["S-11"], wave=1, area=["mcp"], tier="Sonnet", size="S",
  why="213 scan calls (18% of all 1,198 logged calls) have no pattern recorded, `get_section`, `get_span` and `get_paper` rows carry no arguments, errors store only the exception class name, and `source` is constant, so harness replays look like agent sessions (RV-4 F-4.5; review S-11). The usage log is the only evidence base for any future MCP work, and it is blind exactly where agents behave most like brute force.",
  in_=["Bind pattern, method or section path into the existing `query` column, the argument `paper_id`, `result_count` from the result length, `str(e)[:200]` into `error`, and a `--client-label` flag (argparse, not environment) into `source`. No schema change; existing rows stay valid."],
  out=["New columns (top score, returned ids: RV-6 F-A9, not carried by the review). Dashboard changes. Any retrieval change."],
  owns=["app/usage_log.py","app/test_usage_log.py","app/serve.py","app/test_serve.py"],
  commits=["stub: docstring stating the per-tool binding table","failing tests per tool (scan_corpus, scan_methods, get_section, get_span, get_paper, errors)","implementation to green","`--client-label` flag + test"],
  verify=["`conda run -n agent-rag-research python -m pytest -q app/test_usage_log.py app/test_serve.py -o addopts=\"--disable-socket\"`","On a scratch usage database: one mixed fake session then `select tool, query from requests where tool like 'scan%'` shows no NULL query"],
  accept="After one scripted mixed session on fakes, no scan row has a NULL `query` and every get_* row has its `paper_id`; error rows carry the message prefix. Falsified if any tool still writes a NULL where its argument exists.",
  deps=["MC-2"], gates=["OP-2","MC-4"],
  risk="Logging full regex patterns could store sensitive text. Mitigation: the log is local and already stores queries; length is capped. Rollback: revert; rows written stay valid.",
  docs="PROJECT-STATUS section 2 (`--client-label`) via EP-3."),

# ---------------- W1: retrieval ----------------
t(id="RQ-1", slug="three-retrieval-one-liners", title="Fix three one-line retrieval defects (payload, partial rerank, cap)",
  s=["S-09"], wave=1, area=["retrieval"], tier="Sonnet", size="S",
  why="(1) `hybrid_search` requests the full payload (including chunk text) for up to 10,000 hits per arm but uses two fields (`rag/vector_index.py:286,296`; about 50 MB per main query, latency inferred). (2) A malformed partial reranker reply silently drops candidates: nothing checks the scored indices form a permutation before `rag/reranker.py:231`. (3) `max_hits_per_paper` applied together with `paper_id` returns fewer than `k` (RV-1 F-1.7, F-1.8 #7, RV-4 F-4.11; review S-09).",
  in_=["`with_payload=[_EXT_ID_KEY, \"kind\"]` on both arms, after a grep proving no other payload field is read downstream (CONVENTIONS section 14: carry the check).","Raise `PermanentError` when the returned index set is not a permutation of the sent indices.","Skip the per-paper cap when `paper_id` is set."],
  out=["Retry around vector-store calls, fusion depth changes, a reranker-failure fallback (all behaviour changes). Any ranking change: this ticket must leave `Hit` lists identical for queries without a `paper_id` filter."],
  owns=["rag/vector_index.py","rag/test_vector_index.py","rag/reranker.py","rag/test_reranker.py","rag/retriever.py","rag/test_retriever.py"],
  commits=["stub: three docstring lines, one per defect, with the intended behaviour","failing tests: identical `Hit` lists before and after on the fake; a stub client returning 31 of 32 indices raises; `paper_id` plus cap returns `k`","three fixes, one commit each, each green","grep evidence for 'payload fields read downstream' recorded in the commit body"],
  verify=["`conda run -n agent-rag-research python -m pytest -q rag/test_vector_index.py rag/test_reranker.py rag/test_retriever.py -o addopts=\"--disable-socket\"`","Sibling-path check: state in the PR what happens with `paper_id` set and no cap, and with a cap and no `paper_id`"],
  accept="Not a ranking change, so no A/B: the falsifier is that `Hit` id and score lists are identical before and after on the fake for any query without a `paper_id`+cap combination; the 31-of-32 stub raises; the `paper_id`+cap test returns `k`. The EV-16 baselines run on this code, so any real-index difference would show as an unexplained delta against the pre-change commit recorded in each run manifest. Falsified if the identical-hits test fails.",
  deps=[], gates=["RQ-5","RQ-2","EV-13","EV-14"],
  risk="Narrowing the payload could break a reader that silently used another field. Mitigation: the grep and the identical-hits test. Rollback: revert (three independent commits).",
  docs="PROJECT-STATUS ledger via EP-3."),

t(id="RQ-5", slug="shared-sparse-tokens", title="Extract one shared sparse_tokens() used by the index",
  s=["none: RV-1 F-1.10, prerequisite of RIDER-1 item 4"], wave=1, area=["retrieval"], tier="Sonnet", size="S",
  why="The fake vector store keeps its own `lower().split()` (`rag/fakes/fake_vector_store.py:131`) while the real index tokenizes and repairs ligatures in `_sparse_vector`, so a tokenizer change cannot fail any fake-backed test (review item h residual risk 2; RV-1 F-1.10). RIDER-1 item 4 makes the fake import a shared function, but that function must exist first and it is not a protected path.",
  in_=["A small pure module (no vendor import, so vendor isolation holds) exposing `sparse_tokens(text)`, containing exactly today's behaviour including CQ-1's ligature repair, imported by `VectorIndex._sparse_vector`.","A test that pins the checksum of `rag/ligature_map.json` so the map cannot drift silently (review section 2, CQ-1: no test pins it)."],
  out=["Any tokenizer behaviour change (edge-punctuation stripping and BM25 weighting are CQ-17). Editing the fake (RIDER-1). A filter-parity test against an in-memory vector store (RV-1 F-1.10 part 2, not carried by the review)."],
  owns=["rag/sparse_tokens.py","rag/test_sparse_tokens.py","rag/vector_index.py","rag/test_vector_index.py"],
  commits=["stub: module docstring stating 'behaviour-preserving extraction of the tokenizer in `_sparse_vector`'","characterisation tests pinning today's tokens on a sample including damaged ligatures, and the ligature-map checksum","extraction to green; `_sparse_vector` calls it","mutation proof recorded: changing the shared function fails the vector-index tests"],
  verify=["Identical sparse vectors before and after on 200 stored main chunks, read-only (script output quoted; no index touched)","`conda run -n agent-rag-research python -m pytest -q rag/test_sparse_tokens.py rag/test_vector_index.py -o addopts=\"--disable-socket\"`"],
  accept="Sparse vectors for a fixed sample of chunk texts are byte-identical before and after the extraction; mutating the shared function fails the vector-index tests. Falsified if any sampled vector differs.",
  deps=["RQ-1"], gates=["EV-14","CQ-17","RIDER-1"],
  risk="Extraction subtly changes tokens, which would silently desynchronise stored sparse vectors from query tokens. Mitigation: the identical-vectors check. Rollback: revert.",
  docs="PROJECT-STATUS section 2 (new `rag/` module) and the ARCHITECTURE.md module list; the ARCHITECTURE line is in this PR, the ledger via EP-3."),

t(id="RQ-2", slug="opt-in-relevance-demotion", title="Add an opt-in, default-off relevance demotion to the Retriever",
  s=["S-21"], wave=1, area=["retrieval"], tier="Sonnet", size="M",
  why="37.4% of main-corpus papers (4,630 of 12,385) are off-topic against the audited labels and nothing in the pipeline can keep them out of an answer; `papers.relevance_score` separates on from off topic at AUROC 0.923 (RV-1 F-1.4, `docs/eval-reports/2026-11-10-topic-labels-audit.md`), the Retriever already loads the paper record for every reranked hit, and `Config.relevance_filter` is dead. The operator keeps the off-topic papers; the lever is measurement first, demotion only.",
  in_=["`Retriever` keyword arguments (floor value, demote mode) that, when set, move results whose paper `relevance_score` is below the floor after those at or above it, preserving relative order and never removing any result; default off so output is byte-identical to today.","A `--demote-relevance <floor>` flag in `app/retrieval_eval.py`, the same pattern CQ-3 used for `--drop-stub-chunks`, so the arm can be run."],
  out=["A hard drop or a filter (excluded by the frozen topic-focus protocol, section 6). A `Config` field or `SearchFilters.min_relevance` (RIDER-1 item 1 if adopted). The payload-index route (only if RQ-3 observes pool starvation). Choosing the floor: RQ-3's pre-registered arms."],
  owns=["rag/retriever.py","rag/test_retriever.py","app/retrieval_eval.py","app/test_retrieval_eval.py"],
  commits=["stub: docstring stating demote semantics, the default-off identity guarantee, and the flag name that RQ-3's addendum will cite","failing tests: below-floor results follow in-floor ones in original relative order; none removed; `Coverage` unchanged; default off equals baseline on the fake","implementation to green","`--demote-relevance` flag wired and tested"],
  verify=["`conda run -n agent-rag-research python -m pytest -q rag/test_retriever.py app/test_retrieval_eval.py -o addopts=\"--disable-socket\"`","Identity check: with the flag absent, the per-question rows of a fake-backed run are equal before and after"],
  accept="Default-off output is identical to the pre-change commit on the fake (byte-equal result lists); with a floor set, no result is removed and order within each side of the floor is preserved. The retrieval-quality ADOPT/REJECT rule is not applied here: it is frozen in the topic-focus protocol section 6 and applied by RQ-3. Falsified if the default-off identity test fails.",
  deps=["RQ-1","EV-10"], gates=["RQ-3"],
  risk="Demotion acts on the already-truncated pool and can starve it (a pool 40% off-topic still leaves about 19 of 32; RV-1 F-1.4). Mitigation: default off; RQ-3 reports `Coverage` pool sizes. Rollback: revert; nothing depends on it until RIDER-1.",
  docs="PROJECT-STATUS section 2 (flag) via EP-3; no contract or Config change here."),

# ---------------- W1: evaluation instruments ----------------
t(id="EV-7", slug="eval-entrypoints-explicit-collection", title="Require --collection, stamp the fixture hash, preflight gold ids",
  s=["S-02"], wave=1, area=["eval"], tier="Sonnet", size="M",
  why="`--collection` still defaults to None in `app/retrieval_eval.py:780`, `app/escalation_eval.py:153` and `app/score_distribution_census.py:209`, which `build_mcp_server` turns into the main `papers` collection, so a mispointed run yields a plausible low number with `n_errors = 0` (RV-3 F-1.2). Reports stamp no hash of the ground-truth file (contrast `judge_eval`'s `rubric_sha256_12`). EV-5 already fixed the run scripts (fixture hash check, point-count guard, no fixture rewrite, run from the worktree under test); the Python entry points themselves were not touched.",
  in_=["`--collection` `required=True` in the three entry points (precedent: `app/generation_capture.py`).","`ground_truth_sha256_12` in `build_report`, same pattern as `judge_eval`.","Preflight before scoring: every `gold_paper_id` of the loaded questions resolves in the document store, else exit 2 naming the unresolved ids."],
  out=["The run scripts, protocols and addenda (EV-5, done). The collection point-count check (stays in the run scripts' `check-points`). Lock-timeout validity (EV-10). Excerpt metric (EV-8)."],
  owns=["app/retrieval_eval.py","app/test_retrieval_eval.py","app/escalation_eval.py","app/test_escalation_eval.py","app/score_distribution_census.py","app/test_score_distribution_census.py"],
  commits=["stub: docstrings stating the three behaviours (required flag, hash stamp, preflight exit 2)","failing tests for each","implementation to green","docstring/`--help` text updated"],
  verify=["`conda run -n agent-rag-research python -m app.retrieval_eval --help` shows `--collection` as required","Unit test: report hash equals `sha256sum` of the fixture file (first 12 hex)"],
  accept="Running any of the three without `--collection` exits non-zero; the report's `ground_truth_sha256_12` equals the first 12 hex of `sha256sum` of the file; a fixture with an unresolvable gold paper id exits 2 naming it. Falsified if a run without `--collection` still starts.",
  deps=[], gates=["EV-8","EV-16"],
  risk="Existing wrapper scripts that relied on the default break loudly. Mitigation: that is the point; EV-5's run scripts already pass `--collection`. Rollback: revert.",
  docs="PROJECT-STATUS section 2 (flag now required) via EP-3."),

t(id="EV-8", slug="passage-excerpt-hit-metric", title="Add an excerpt-containment passage metric that honours alternative gold chunks",
  s=["S-03"], wave=1, area=["eval"], tier="Sonnet", size="M",
  why="`load_questions` never reads `alternative_gold_chunk_ids`, so passage hit is under-counted by up to 13% of items (papers 8 of 61, books 4 of 74) and scoring by chunk identity makes the sets incomparable across any re-chunk (RV-3 F-1.5, review S-03). Anchor-equality also credits any fragment of the gold block (5 of 119 gold anchors are shared by a sibling chunk: about 4% lenient false hits; RV-1 F-1.3).",
  in_=["Additive metric `passage_excerpt_hit`: a returned `passage_text` contains the normalised gold excerpt or an alternative's excerpt (reuse `retrieval_eval._normalized`; alternatives resolved through the document store the harness already holds). Items with a null `excerpt_block_id` (excerpt spans blocks) fall back to the anchor rule and are listed separately.","The anchor rule stays byte-identical and the report stamps `scoring_rule` for both. State in the docstring how this relates to EV-6's member-passage metric (`scripts/eval_strata_report.py`) and the frozen protocols; if the names collide, add an addendum rather than redefining."],
  out=["Editing any ground-truth file (EV-11). Chunk ids in reports (EV-9). Changing the Waymo frozen scoring rule."],
  owns=["app/retrieval_eval.py","app/test_retrieval_eval.py"],
  commits=["stub: docstring defining `passage_excerpt_hit`, its null-excerpt fallback and the ceiling arithmetic (an item can only be a hit if the excerpt is in some chunk the pool can contain)","failing test: FakeRetriever returning an alternative chunk is a hit under the excerpt rule and a miss under the anchor rule","implementation to green; `scoring_rule` stamp","report fields and by-stratum split added"],
  verify=["`conda run -n agent-rag-research python -m pytest -q app/test_retrieval_eval.py -o addopts=\"--disable-socket\"`","Existing Waymo-fixture scoring tests unchanged and green (anchor rule untouched)"],
  accept="A FakeRetriever test returning an alternative chunk is a hit under the excerpt rule and a miss under the anchor rule; Waymo anchor-rule results are byte-identical on the existing test fixtures. This is an instrument, not a retrieval change: its ceiling check is that on the gold chunk itself the excerpt metric equals 1 for every non-null-excerpt item. Falsified if the gold chunk fails its own excerpt check on any fixture item.",
  deps=["EV-7"], gates=["EV-9","EV-11","EV-16"],
  risk="Two metrics diverge in meaning from EV-6's member-passage metric and confuse later reports. Mitigation: the docstring reconciliation and one stamped `scoring_rule`. Rollback: revert; additive.",
  docs="PROJECT-STATUS section 2 via EP-3."),

t(id="EV-9", slug="chunk-ids-in-eval-rows", title="Record retrieved chunk ids in eval rows; match stubs by chunk id",
  s=["S-05"], wave=1, area=["eval"], tier="Sonnet", size="S",
  why="Report rows carry only `retrieved_block_ids` (`app/retrieval_eval.py:229,371,551`), and `scripts/list_stub_chunks.py` identifies a stub by its anchor block, which is ambiguous for the 7.5% of standards chunks that share an anchor (35,714 chunks, 33,053 distinct anchors; RV-1 F-1.3, review section 2 on CQ-3). The CQ-3 addendum (EV-12) needs per-chunk identity.",
  in_=["Add `retrieved_chunk_ids` to the per-question row. `GroundedResult` has no chunk id, so recover it from (paper id, anchor block id, passage text) through the document store the harness already holds; where two chunks match, record both and mark the row ambiguous.","`scripts/list_stub_chunks.py --ab` matches stubs by chunk id."],
  out=["Any `contracts/` change. If chunk ids cannot be recovered without one, STOP and report: that is a RIDER-1 candidate, not an edit."],
  owns=["app/retrieval_eval.py","app/test_retrieval_eval.py","scripts/list_stub_chunks.py","scripts/test_list_stub_chunks.py"],
  commits=["stub: docstring of the recovery rule and the ambiguity marker","failing tests: unique recovery; duplicate-text ambiguity marked; stub-at-rank-1 share computed by chunk id equals anchor-based share where anchors are unique, and differs on a shared-anchor fixture","implementation to green","list_stub_chunks wired"],
  verify=["`conda run -n agent-rag-research python -m pytest -q app/test_retrieval_eval.py scripts/test_list_stub_chunks.py -o addopts=\"--disable-socket\"`"],
  accept="On a fixture with two chunks sharing one anchor, the stub-at-rank-1 share is computed per chunk and the anchor-based figure is shown to differ; ambiguous rows are counted, not hidden. Falsified if recovery silently picks one of two matching chunks.",
  deps=["EV-8"], gates=["EV-10","EV-12","EV-21"],
  risk="Recovery by text may be slow on 30,000-chunk papers. Mitigation: per-paper lookup, cached. Rollback: revert; additive field.",
  docs="PROJECT-STATUS section 2 via EP-3."),

t(id="EV-10", slug="invalid-run-on-lock-timeout", title="Mark an eval run invalid when any error is a GPU lock timeout",
  s=["S-06"], wave=1, area=["eval"], tier="Sonnet", size="S",
  why="Lock-timeout errors are scored as ordinary misses by `app/retrieval_eval.py`'s per-hit resilience: in SB-1 two eval jobs sat more than 20 minutes behind a long GPU job and some questions timed out and were counted as misses (RV-6 F-A8, `docs/eval-reports/2026-08-28-sb1-chunk-boundary.md`). Wave 2 is exactly the concurrent-GPU scenario.",
  in_=["Count questions whose error is a lock timeout; if any, write `run_valid: false` and the count in the report header and exit non-zero instead of scoring them as misses."],
  out=["The lock holder identity (OP-5). Retrying timed-out questions."],
  owns=["app/retrieval_eval.py","app/test_retrieval_eval.py"],
  commits=["stub: docstring stating the invalid-run rule","failing test: a stubbed lock-timeout error yields `run_valid: false` and a non-zero exit","implementation to green","report header field documented"],
  verify=["`conda run -n agent-rag-research python -m pytest -q app/test_retrieval_eval.py -o addopts=\"--disable-socket\"`"],
  accept="A stubbed lock timeout on one question makes the whole report invalid and the process exit non-zero; a run with no timeouts is unchanged. Falsified if the timeout question is still counted as a miss.",
  deps=["EV-9"], gates=["RQ-2","EV-16"],
  risk="A transient timeout on one question invalidates a long run. Mitigation: intended (a partially starved run is not a baseline); the run is repeatable. Rollback: revert.",
  docs="PROJECT-STATUS via EP-3."),

t(id="EV-11", slug="record-alternatives-refreeze-hashes", title="Record note-only duplicates as alternatives and re-freeze fixture hashes",
  s=["S-03"], wave=1, area=["eval"], tier="Sonnet", size="S",
  why="Cross-verification found three same-document duplicates recorded only as 'survive' notes (Q-STD-D-014, D-027, D-028) that are not in `alternative_gold_chunk_ids`, so a correct answer from the duplicate scores a miss (RV-3 F-1.5, review S-03). Fixing it changes a frozen fixture, so it must happen before any run and under a dated addendum, because the frozen protocols record each fixture's SHA-256.",
  in_=["Dated addendum to the standards protocol first (commit 1), then record the duplicates as alternatives in the standards ground-truth file, make `merge_gt` tolerate per-item orphans (report them, write the rest, fail only above a stated percentage), and update the standards, books and papers entries in `docs/eval-reports/data/2026-11-10-FIXTURE-HASHES.json`."],
  out=["Rewriting any question or gold excerpt. Collapsing the three `gt_tools.py` copies. The focus-set hash entry (EV-4). Promotion into `fixtures/eval/` (RIDER-1)."],
  owns=["docs/eval-reports/data/2026-11-10-standards-gt/","docs/eval-reports/data/2026-11-10-causal-books-gt/","docs/eval-reports/data/2026-11-10-papers-passage-gt/gt_tools.py","docs/eval-reports/data/2026-11-10-FIXTURE-HASHES.json","docs/eval-reports/2026-11-10-standards-benchmark-protocol.md"],
  commits=["stub: addendum text (what changes, why it is pre-run, the new hash procedure) appended to the standards protocol BEFORE any fixture edit","three duplicates recorded as alternatives; per-item orphan tolerance in `merge_gt` with tests or a dry-run transcript","new hashes written to FIXTURE-HASHES.json for the files that changed","`scripts/eval_protocol_tools.py check-hash` transcript quoted"],
  verify=["`conda run -n agent-rag-research python scripts/eval_protocol_tools.py check-hash docs/eval-reports/data/2026-11-10-FIXTURE-HASHES.json <fixture-relative-path>` passes for each fixture","`git log --format=%H -- docs/eval-reports/data/2026-11-10-FIXTURE-HASHES.json` shows the addendum commit precedes the hash change"],
  accept="Addendum commit precedes the fixture edit; the three duplicates appear as alternatives; hashes in the file equal `sha256sum` of each fixture; no question text or excerpt changed (diff shows only alternatives and the hash file). Falsified if `git diff` shows any other change in a fixture.",
  deps=["EV-8"], ext=["EV-4"], gates=["EV-12","EV-16","EV-18","RIDER-1"],
  risk="A hash edit after a run would void that run. Mitigation: ordered before wave 2 by dependency. The hash file is shared with in-progress EV-4 (focus entry): edits are key-disjoint and EV-4 merges first. Rollback: revert the fixture and hash commits together.",
  docs="Standards protocol addendum is the doc; PROJECT-STATUS via EP-3."),

t(id="EV-12", slug="cq3-preregistration-addendum", title="Amend the CQ-3 stub A/B pre-registration (fixtures, minimum effect)",
  s=["S-05"], wave=1, area=["eval"], tier="Sonnet", size="S",
  why="CQ-3's pre-registration names the wrong fixtures (the 210-question set and the legacy books set, which have no passage gold), has no minimum effect so one noise flip would ADOPT, and identifies stubs by anchor (ambiguous for 7.5% of standards chunks); the stub length threshold also differs across three tools (40, 60 and 80 characters; review section 2).",
  in_=["Dated addendum appended to `docs/eval-reports/2026-11-10-cq3-stub-chunks.md`: fixtures are the standards, causal-books and papers-passage sets (post-EV-11 hashes); ADOPT needs net +3 items on at least one set and no stratum losing more than 1; stubs identified by chunk id (EV-9); the single binding stub definition for this A/B is the retriever's (40 characters) with the other two tools' thresholds stated as non-binding."],
  out=["Changing any threshold in code (the three tools stay as they are). Running the A/B (EV-21). Editing the original pre-registration text: append only."],
  owns=["docs/eval-reports/2026-11-10-cq3-stub-chunks.md"],
  commits=["stub: addendum heading with date and the four amendments as a list, committed before any stub A/B report exists","addendum text with ceiling arithmetic for the new minimum effect (n of each set vs +3)","cross-check that every number cited resolves to a file"],
  verify=["`git log --diff-filter=A --format='%H %cI' -- <any stub A/B report>` shows no such file older than this addendum's commit"],
  accept="Addendum is committed before any stub A/B report exists and states fixtures, ADOPT rule (net +3 on one set, no stratum worse by more than 1), chunk-id matching and the binding threshold; the ceiling note shows +3 is reachable on each set (n=94, 69, 61 answerable). Falsified if a stub A/B report predates the addendum.",
  deps=["EV-9","EV-11"], gates=["EV-21"],
  signoff="n (not a protected path); the amended rule is a decision for the operator in PR review.",
  risk="Low. An addendum cannot undo a result already seen; ordering is enforced by dependency. Rollback: revert.",
  docs="PROJECT-STATUS via EP-3."),

t(id="EV-13", slug="rerank-score-capture-and-census", title="Capture cross-encoder scores and build the absence census tool",
  s=["S-04"], wave=1, area=["eval","retrieval"], tier="Sonnet", size="M",
  why="Callers get the fusion (RRF) score and the reranker's score is discarded (`rag/retriever.py:249`, `rag/reranker.py:231`), so the earlier 'no score floor' verdict tested rank arithmetic only; the cross-encoder score is the one cheap absence signal nobody has censused (review item a; RV-1 F-1.1, RV-4 F-4.1). A CRAG instrument (AUROC 0.94 and 0.80) and MiniCheck are independent of this and stay as they are.",
  in_=["Experiment-only `rerank_scored()` on `TeiReranker` returning `(candidate, score)` pairs, no contract change, `rerank()` untouched.","`app/exp_rerank_score_census.py`: answerable top-1 reranker score versus the absent arms (standards absent 9 and partial-absent 13 reported separately; main known-absent 24; books partial-absent 5; Waymo 12 and 14), AUROC with Hanley-McNeil interval, reusing `auroc_pos_higher` from `exp_agentic_loop_v0` and `_iqr_separates` from the score census; explicit `--collection`, `--db-path`, `--blob-dir`. Definition frozen in the standards protocol section 7 (iii)."],
  out=["Exposing the score to callers (RQ-4, gated). Running it (EV-19, GPU). Any threshold or wiring decision (needs 60 or more distinct absent items; RV-3 F-1.10)."],
  owns=["rag/reranker.py","rag/test_reranker.py","app/exp_rerank_score_census.py","app/test_exp_rerank_score_census.py"],
  commits=["stub: docstrings of `rerank_scored` and the census CLI; the frozen definition cited by section number","failing tests: scores returned are monotone in the order `rerank()` returns; census on a fake reranker computes the expected AUROC and CI","implementation to green","census CLI with required collection flags"],
  verify=["`conda run -n agent-rag-research python -m pytest -q rag/test_reranker.py app/test_exp_rerank_score_census.py -o addopts=\"--disable-socket\"`","Reuse stated: `auroc_pos_higher`, `_iqr_separates`, Hanley-McNeil helper (no new statistics code)"],
  accept="Unit test: `rerank_scored` scores are monotone with `rerank()` order; the census reproduces a hand-computed AUROC on a fixture of 6 items. Falsified if `rerank()` output changes by even one id on the existing reranker tests.",
  deps=["RQ-1"], gates=["EV-19"],
  risk="Adding a method to a real adapter widens its surface. Mitigation: documented experiment-only; fakes are untouched (protected). Rollback: revert.",
  docs="PROJECT-STATUS section 2 (new `app/` entry point) via EP-3."),

t(id="EV-15", slug="bm25-floor-script", title="Add the plain BM25 floor script named EV-5b in the protocols",
  s=["S-02"], wave=1, area=["eval"], tier="Sonnet", size="S",
  why="The frozen protocols require a BM25 'instrument floor' printed beside every run, but their own text says it is not available at first run: the lane's script was scratch (needs numpy, scipy and sklearn) and nothing is committed. They name it 'EV-5b', a follow-up script ticket (standards protocol section 7 (ii); topic-focus protocol section 7 (ii); RV-3 F-1.3 (b)). Without it every run reports a number with no floor.",
  in_=["`scripts/bm25_floor.py`: plain BM25 (k1 = 1.2, b = 0.75, tokens as specified in the standards protocol) over the stored chunk text of a corpus database opened read-only, scoring a ground-truth file at paper and passage level; no new dependency (standard library only)."],
  out=["Any claim that BM25 predicts the system's score. Wiring it into run scripts (EV-16 runs it as a separate step). Using the system's sparse arm."],
  owns=["scripts/bm25_floor.py","scripts/test_bm25_floor.py"],
  commits=["stub: docstring stating the frozen definition and that the database is opened `mode=ro`","failing tests on a 20-chunk toy corpus with known BM25 scores","implementation to green","reproduction check against the review's figures on the standards database"],
  verify=["`conda run -n agent-rag-research python scripts/bm25_floor.py --db <standards.db> --ground-truth docs/eval-reports/data/2026-11-10-standards-gt/standards_gt.json` prints paper R@10 near 0.98 and chunk@10 near 0.63 (the review's re-run values, tolerance stated)"],
  accept="Standards floor reproduces the review's re-run within the tolerance stated in the protocol (paper R@10 0.98, chunk@10 0.63, chunk@1 0.23 on the 94 answerable items). Falsified if the script cannot reproduce those figures from the same stored text.",
  deps=[], gates=["EV-16","EV-17","EV-18"],
  risk="A tokenisation difference makes the floor differ from the one the protocols quote. Mitigation: the reproduction check and the stated tolerance. Rollback: revert.",
  docs="PROJECT-STATUS section 2 via EP-3."),

t(id="EV-14", slug="payload-index-overlap-measurement", title="Measure filtered-search overlap with exact search on a clone",
  s=["S-15"], wave=1, area=["eval","retrieval"], tier="Sonnet", size="M",
  why="No payload index exists on any live collection (every segment's `payload_index/config.json` is `{\"indexed_fields\":{}}`; 8, 7 and 8 segments), yet every query is filtered. The recall loss is inferred from the vector store's documented design, not measured; the real risk band is mid-selectivity filters (`kind=summary` is 3% of points and is the whole `search_papers` path; `doc_type=book`) (review item b; RV-1 F-1.2).",
  in_=["On a clone made with `VectorIndex.clone_points_into` (never the live collection): use 100 stored summary vectors as queries and compare exact search with the default HNSW search for `kind=summary`, `doc_type=book` and a single `paper_id`; report overlap@k per filter. Reuse CQ-2's read-only sampling helpers; if an exact-search method is missing from `VectorIndex`, add one small read-only method there (vendor SDK calls stay inside that adapter).","Pre-registered falsifier (commit 1): HNSW overlap with exact is at least 0.99 on all three filters, then payload-index work (CQ-9) is closed."],
  out=["Creating payload indexes (CQ-9). Touching the live collection. Any GPU use: stored vectors are the queries, nothing is embedded."],
  owns=["rag/vector_index.py","rag/test_vector_index.py","scripts/payload_index_overlap.py","scripts/test_payload_index_overlap.py","docs/eval-reports/data/<run-date>-payload-index-overlap/"],
  commits=["stub: report skeleton with the pre-registered 0.99 falsifier and the three filters, committed before the clone is made","exact-search read-only method and the script, unit-tested against mocked clients","clone created; dry run on 10 queries; free space recorded","full run; report with the overlap table and the verdict"],
  verify=["`df -h /` before cloning (needs 6-8 GB free per clone, review F2)","`conda run -n agent-rag-research python scripts/payload_index_overlap.py --help` shows required `--collection` and a `--target-is-clone` guard","Report table has one row per filter with overlap@10 and the count of queries returning fewer than k"],
  accept="Report states overlap of HNSW versus exact for each of the three filters. Verdict is mechanical: all three at least 0.99 closes the finding; any below 0.99 opens CQ-9. Falsified (finding closed) if all three are 0.99 or more. The clone is deleted afterwards and its deletion is recorded.",
  deps=["RQ-5","OP-4"], ext=["F2"], gates=["CQ-9"],
  services="vector store (CPU container) up; no embedder, no reranker",
  needs_note="vector store start approved (operator question F2) and 6-8 GB free for one clone",
  risk="Cloning on a 98%-full disk. Mitigation: OP-4 first, free-space check, one clone at a time, deleted after. The live collection is only read. Rollback: delete the clone.",
  docs="Report is the doc; PROJECT-STATUS section 5/6 via EP-3."),

# ---------------- W1: corpus ----------------
t(id="CQ-7", slug="ligature-resparse-clone-cpu", title="Build a ligature-repaired clone of the main collection on CPU",
  s=["S-17"], wave=1, area=["corpus"], tier="Sonnet", size="M",
  why="CQ-1 repairs ligature damage in the sparse arm but is deliberately not applied to any index, and CQ-2 added `app.resparse` to recompute sparse vectors without re-embedding. The A/B (EV-22) needs a repaired clone to exist, and the whole preparation is CPU-only, so it can run while the GPU is held by another process (GPU-day runbook step 5.1). About 35% of main-corpus chunks change; resparse time is unmeasured.",
  in_=["Clone the main collection with `VectorIndex.clone_points_into` into a new scratch collection, then `app.resparse --collection <scratch> --target-is-clone --clone-of <live> --apply` after a dry run, following `docs/eval-reports/2026-11-10-cq2-index-maintenance.md`. Record measured resparse time and the sparse-staleness sample before and after."],
  out=["Touching the live collection (read-only source only). The A/B (EV-22). Any BM25 weighting (CQ-17). Deleting the clone: EV-22 does that when done."],
  owns=["docs/eval-reports/data/<run-date>-ligature-clone/"],
  commits=["stub: record skeleton with the dry-run and apply checklists and the abort rule (under 20 GB free)","dry run output saved","apply on the clone; times and counts recorded; staleness sample before/after","handover note for EV-22 (collection name, git revision of the resparse code)"],
  verify=["`df -h /` before the clone","`conda run -n agent-rag-research python -m app.resparse --help` shows `--collection` required and `--target-is-clone`","Post-apply sparse-staleness sample reports the stale share near zero on the clone and unchanged on the live collection"],
  accept="Scratch collection holds the same point count as the live one; resparse applied only to the scratch collection; staleness sample on the scratch shows the repaired vectors, on the live shows unchanged. Falsified if the live collection's point count or sampled sparse vectors changed at all.",
  deps=["OP-4"], ext=["F2"], gates=["EV-22"],
  services="vector store (CPU container) up; no GPU services",
  needs_note="vector store start approved (F2); 6-8 GB free for the clone",
  risk="Applying resparse to the live collection by mistake (the documented CQ-1 deployment hazard). Mitigation: `--target-is-clone` guard, explicit `--collection` on every command, live collection read-only. Rollback: delete the scratch collection.",
  docs="CQ-2 operating note is the reference; record is the doc; PROJECT-STATUS via EP-3."),

t(id="CQ-8", slug="rechunk-reuse-vectors-by-text-hash", title="Make rechunk re-embed only chunks whose text changed",
  s=["S-14"], wave=1, area=["corpus"], tier="Sonnet", size="M",
  why="`app/rechunk.py:189` re-embeds every chunk of a re-chunked paper, including unchanged text, which multiplies the cost of every re-chunk the later tickets want (RV-2 F-2.3 step 1; review S-14). Chunk ids are positional, so reuse must key on a text hash, not on the id.",
  in_=["Look up stored vectors for identical chunk text (hash of the embedded text) in the same collection, reuse them, and embed only new text. Guard: reuse only from the same collection and embedder model name."],
  out=["Content-addressed chunk ids (explicitly rejected: 'Will not do' table). Changing the chunker. Applying to any live index."],
  owns=["app/rechunk.py","app/test_rechunk.py"],
  commits=["stub: docstring stating the reuse rule and its guards","failing test: a text-only change to one chunk of a 10-chunk paper re-embeds exactly one chunk (fake embedder call count)","implementation to green","dry-run report line 'reused N, embedded M'"],
  verify=["`conda run -n agent-rag-research python -m pytest -q app/test_rechunk.py -o addopts=\"--disable-socket\"`","Mutation proof: disable the reuse path and the call-count test fails"],
  accept="Dry run on a fixture of 10 papers with a text-only change: re-embedded count equals changed-text count and reused count equals the rest; a changed embedder model name disables reuse. Falsified if the call-count test passes with reuse disabled.",
  deps=[], gates=["CQ-10","CQ-15"],
  risk="A wrongly reused vector silently pairs old text with a new position. Mitigation: vectors depend only on the embedded text (which includes title and section path prefix), guarded by model name. Rollback: revert.",
  docs="PROJECT-STATUS via EP-3."),
